#!/bin/bash
set -e
mkdir -p work/data/pgo-full-train work/pgo-full-out work/pgo-full-profile
awk -v out=/workspace/work/data/pgo-full-train -f work/pgo-full-gen.awk
docker run --rm -v /var/lib/docker/vfs/dir/9e1e982dbef583bad7592026324908fca27fe998b6e59acf2aebdbe9d6d438c2:/gcc:ro -v /workspace/work:/gcc/mnt --tmpfs /gcc/tmp:rw,size=256m busybox:1.37 chroot /gcc /bin/bash -c 'export PATH=/usr/local/bin:/usr/bin:/bin; cd /mnt; set -e; g++ -O3 -std=c++17 -pthread -flto -static -s -fprofile-generate=/mnt/pgo-full-profile -fprofile-update=atomic -o bin/pgo_full variants/fix_atomic.cpp; SD_DATA=/mnt/data/pgo-full-train SD_OUT=/mnt/pgo-full-out SD_THREADS=4 bin/pgo_full; g++ -O3 -std=c++17 -pthread -flto -static -s -fprofile-use=/mnt/pgo-full-profile -fprofile-correction -o bin/pgo_full variants/fix_atomic.cpp; cp bin/pgo_full bin/pgo_full_plain; g++ -O3 -std=c++17 -pthread -flto -static -s -fprofile-use=/mnt/pgo-full-profile -fprofile-correction -fprofile-partial-training -o bin/pgo_full variants/fix_atomic.cpp; cp bin/pgo_full bin/pgo_full_partial; g++ -O3 -std=c++17 -pthread -flto -static -s -fprofile-use=/mnt/pgo-full-profile -fprofile-correction -fprofile-partial-training -fno-peel-loops -fno-unroll-loops -o bin/pgo_full variants/fix_atomic.cpp; cp bin/pgo_full bin/pgo_full_nounroll'
